const showSetupPrevious27=showBattleSetup24;
showBattleSetup24=function(){if(!duelActive24()&&save.teamBattle27.mode==='solo'&&!formation27()[0]){const first=GAME_DATA.cards.find(c=>save.cards[c.id]);formation27()[0]=save.cards[selectedCard24]?selectedCard24:first?.id||null;persist();}showSetupPrevious27();};
/* v2.7: formation UI. Card data, dice and skill calculations remain shared with v2.6.1. */
let selectedSlot27=0;
function mode27(){return TEAM_MODES27[save.teamBattle27.mode];}
function formation27(){return save.teamBattle27.formations[save.teamBattle27.mode];}
function card27(id){return GAME_DATA.cards.find(c=>c.id===id);}
function assignSlot27(id){if(!save.cards[id])return;const ids=formation27(),other=ids.indexOf(id),previous=ids[selectedSlot27];if(other>=0&&other!==selectedSlot27)ids[other]=previous;ids[selectedSlot27]=id;persist();renderBattleSetup24();}
function moveSlot27(i,j){const ids=formation27();if(j<0||j>=ids.length)return;[ids[i],ids[j]]=[ids[j],ids[i]];selectedSlot27=j;persist();renderBattleSetup24();}
renderBattleSetup24=function(){const owned=GAME_DATA.cards.filter(c=>save.cards[c.id]);if(!owned.some(c=>c.id===selectedCard24))selectedCard24=owned[0]?.id||null;const config=save.teamBattle27,m=mode27(),ids=formation27();selectedSlot27=Math.min(selectedSlot27,m.size-1);
 $('#battleRecord24').textContent=`${wallet24().wins}勝 ${wallet24().losses}敗 ${wallet24().draws}引き分け ／ 勝利報酬の残り ${wallet24().rewardCharges}回`;
 $('#teamModes27').innerHTML=Object.entries(TEAM_MODES27).map(([k,v])=>`<button data-mode27="${k}" aria-pressed="${config.mode===k}" class="${config.mode===k?'primary':'ghost'}">${v.name}<small>${v.size}枚・★${v.cap}まで</small></button>`).join('');
 $$('[data-mode27]').forEach(b=>b.onclick=()=>{config.mode=b.dataset.mode27;selectedSlot27=0;persist();renderBattleSetup24()});
 $('#teamFormation27').innerHTML=`<div class="formation-title27"><b>出場順を決めよう</b><span>① 枠を選ぶ → ② 下のカードを選ぶ → ③ 枠に入れる</span></div><div class="team-slots27">${ids.map((id,i)=>{const c=card27(id);return `<div class="team-slot27 ${selectedSlot27===i?'chosen27':''}"><button class="slot-main27" data-slot27="${i}" aria-pressed="${selectedSlot27===i}"><small>${i+1} · ${m.positions[i]}</small>${c?`<img src="${ART[c.id]}" alt=""><b>${c.name}</b><span>${c.ultra?'UR · ':''}★${c.rarity} ／ ${['通常','覚醒Ⅰ','覚醒Ⅱ','キラMAX'][level26(c)]}</span>`:'<b>＋ カードを選ぶ</b><span>この枠を選択</span>'}</button><div class="slot-order27"><button class="small ghost" data-move27="${i}" data-to27="${i-1}" ${i===0?'disabled':''} aria-label="${m.positions[i]}を前へ">← 前へ</button><button class="small ghost" data-move27="${i}" data-to27="${i+1}" ${i===ids.length-1?'disabled':''} aria-label="${m.positions[i]}を後ろへ">後ろへ →</button><button class="small ghost" data-remove27="${i}" ${!c?'disabled':''}>外す</button></div></div>`}).join('')}</div>`;
 $$('[data-slot27]').forEach(b=>b.onclick=()=>{selectedSlot27=+b.dataset.slot27;if(ids[selectedSlot27])selectedCard24=ids[selectedSlot27];renderBattleSetup24()});
 $$('[data-move27]').forEach(b=>b.onclick=()=>moveSlot27(+b.dataset.move27,+b.dataset.to27));$$('[data-remove27]').forEach(b=>b.onclick=()=>{ids[+b.dataset.remove27]=null;persist();renderBattleSetup24()});
 const check=validateTeam27(ids,config.mode,save.cards);$('#teamCost27').className=check.ok?'cost27 valid27':'cost27';$('#teamCost27').innerHTML=`<div>${ids.map(id=>card27(id)?'★'+card27(id).rarity:'未選択').join(' ＋ ')}<strong>TOTAL ★${check.cost} / ★${m.cap}</strong></div><p>${check.message}</p>`;
 $('#startDuel24').disabled=!check.ok;$('#startDuel24').textContent=`${m.name} · このチームで出撃`;
 $('#battleTabs24').innerHTML=[{id:'all',name:'すべて'},...GAME_DATA.eras].map(e=>`<button data-battle-tab="${e.id}" class="${battleFilter24===e.id?'active':''}">${e.name}</button>`).join('');$$('[data-battle-tab]').forEach(b=>b.onclick=()=>{battleFilter24=b.dataset.battleTab;renderBattleSetup24()});
 $('#battleCollection24').innerHTML=owned.filter(c=>battleFilter24==='all'||c.era===battleFilter24).map(c=>`<button class="card-slot ${selectedCard24===c.id?'selected24':''}" data-duel-card="${c.id}" aria-pressed="${selectedCard24===c.id}">${miniCard(c)}<span class="assigned27">${ids.includes(c.id)?m.positions[ids.indexOf(c.id)]+'に編成中':'★'+c.rarity+'で編成'}</span></button>`).join('')||'<p class="empty24">この時代のカードはまだありません。タイピングでポイントを貯め、時空召喚で手に入れよう。</p>';
 $$('[data-duel-card]').forEach(b=>b.onclick=()=>{selectedCard24=b.dataset.duelCard;if(config.mode==='solo')assignSlot27(selectedCard24);else {renderBattleSetup24();$('#battleSelected24').scrollIntoView({behavior:'instant',block:'center'});}});
 const c=card27(selectedCard24);$('#battleSelected24').innerHTML=c?battleSelectedMarkup24(c)+`<div class="assign-panel27"><b>★${c.rarity} ／ ${['通常','覚醒Ⅰ','覚醒Ⅱ','キラMAX'][level26(c)]}</b><button id="assignCard27" class="primary">${m.positions[selectedSlot27]}に入れる</button><small>同じカードはチームに1枚まで。選択済みなら枠を入れ替えます。</small></div>`:'<div class="empty24"><h3>最初の一枚が、君の相棒。</h3><p>タイピングで300 ptを貯めたら、時空召喚へ。</p></div>';
 $('#previewCard24')?.addEventListener('click',()=>showBattleCard24(c));$('#assignCard27')?.addEventListener('click',()=>assignSlot27(c.id));
};
$('#startDuel24').onclick=()=>startDuel24();
startDuel24=function(){if(duelActive24())return;const mode=save.teamBattle27.mode,ids=formation27().slice();if(!validateTeam27(ids,mode,save.cards).ok)return;duel24=createMatch27(ids,cpuTeam27(mode),mode);duelToken24++;wallet24().pendingBattle=true;persist();audioSys.start();showScreen('cardDuel');audioSys.set('boss');$('#duelFormula24').innerHTML='';$('#duelSkill24').innerHTML='';renderDuel24();const token=duelToken24;setTimeout(()=>{if(token===duelToken24&&duel24?.phase==='intro'&&!duel24.ended)beginTeamFight27();},matchMedia('(prefers-reduced-motion: reduce)').matches?600:2400);};
function beginTeamFight27(){const d=duel24;if(!d||d.ended||d.phase!=='intro')return;d.phase='fight';d.busy=false;renderDuel24();$('#duelMessage24').textContent='先鋒戦！ 作戦を選んで勝負。';entrance261();}
function rosterMarkup27(team,index,label){return `<div class="roster-side27"><div class="roster-head27"><b>${label}</b><span>残り ${team.filter(x=>!x.defeated).length} / ${team.length}</span></div><div class="roster-row27">${team.map((x,i)=>`<div class="roster-member27 ${x.defeated?'defeated27':i===index?'active27':'reserve27'}"><img src="${ART[x.id]}" alt=""><div><small>${x.position} · ★${x.card.rarity}</small><b>${x.card.name}</b><span>${x.defeated?'× DEFEATED':i===index?'● 戦闘中　HP '+x.hp:'○ 控え'}</span></div></div>`).join('')}</div></div>`;}
function briefTeam27(team,label){return `<div><h3>${label} <small>★${team.reduce((n,x)=>n+x.card.rarity,0)}</small></h3>${team.map(x=>`<div class="brief-member27"><img src="${ART[x.id]}" alt=""><span><small>${x.position} · ★${x.card.rarity}</small><b>${x.card.name}</b></span></div>`).join('')}</div>`;}
const renderSoloDuel27=renderDuel24;
renderDuel24=function(){const d=duel24;if(!d)return;renderSoloDuel27();if(!d.playerTeam)return;
 $('#duelRound24').textContent=`${TEAM_MODES27[d.mode].name} · 勝ち抜き戦 ／ TURN ${d.round}`;
 $('#teamStatus27').innerHTML=rosterMarkup27(d.playerTeam,d.pIndex,'PLAYER')+rosterMarkup27(d.cpuTeam,d.cIndex,'CPU');
 for(const [side,team,index] of [['player',d.playerTeam,d.pIndex],['cpu',d.cpuTeam,d.cIndex]]){const x=team[index],el=$('#'+side+'Fighter24');el.querySelector('.fighter-name24 span').textContent=(side==='player'?'PLAYER':'CPU')+' · '+x.position+(x.card.ultra?' · UR':'');el.classList.toggle('down27',x.defeated);}
 $('#teamBrief27').hidden=d.phase!=='intro';if(d.phase==='intro'){$('#teamBrief27').innerHTML=`<div class="eyebrow">${TEAM_MODES27[d.mode].name} / TEAM ENCOUNTER</div><h2>この順番で、勝負！</h2><div class="brief-grid27">${briefTeam27(d.playerTeam,'PLAYER')}<b class="brief-vs27">VS</b>${briefTeam27(d.cpuTeam,'CPU')}</div><button id="beginFight27" class="primary">先鋒戦へ →</button>`;$('#beginFight27').onclick=beginTeamFight27;$('#duelMessage24').textContent='両チームの出場順を確認しよう。';}
 if(d.phase==='switch'&&!d.ended){$('#duelMessage24').textContent=d.transitionText;$('#duelActions24').querySelectorAll('button').forEach(b=>b.disabled=true);}
 if(d.ended){$('#teamBrief27').hidden=true;const resultTitle=d.outcome==='win'?'VICTORY':d.outcome==='loss'?'DEFEAT':'DRAW';const results=`<div class="team-result27"><div class="result-banner27">${resultTitle}</div><p>君のチームの記録</p><div class="result-roster27">${d.playerTeam.map((x,i)=>`<div class="result-member27 ${x.defeated?'result-down27':''} ${!x.defeated&&i===d.pIndex?'survivor27':''}"><small>${x.position}</small>${miniCard(x.card)}<b>${x.kills>=2?x.kills+'人抜き！':x.kills?'1人撃破！':''}</b><span>${x.defeated?'DEFEATED':i===d.pIndex?'生存 · HP '+x.hp:'控え · HP '+x.hp}</span></div>`).join('')}</div></div>`;$('#duelFinish24').insertAdjacentHTML('afterbegin',results);}
};
const rollSolo27=rollDuel24;
rollDuel24=function(stance){if(duel24?.phase!=='fight')return;rollSolo27(stance);};
settleDuel24=function(da,db,stance,cpuStance){const d=duel24;if(!d||d.ended||d.phase!=='fight')return;const {r,deadP,deadC,outcome}=applyTurn27(d,da,db,stance,cpuStance);
 d.logs.push(`${r.player.active?'<strong>◆ '+d.player.skill+'！</strong><br>':''}${r.cpu.active?'<strong>CPU ◆ '+d.cpu.skill+'！</strong><br>':''}<b>TURN ${d.round}</b> ${d.player.name}（${d.playerTeam[d.pIndex].position}）vs ${d.cpu.name}（${d.cpuTeam[d.cIndex].position}）<br>あなた：${STANCES24[stance].name} ／ CPU：${STANCES24[cpuStance].name}<br>${clashLine24('あなた',r.player,r.cpu,r.toCPU)}<br>${clashLine24('CPU',r.cpu,r.player,r.toPlayer)}`);
 d.busy=false;audioSys.sfx(r.player.active?'critical':'hit');
 if(outcome){d.phase='ended';completeDuel24(outcome);}else if(deadP||deadC){d.phase='switch';d.busy=true;d.transitionText=[deadP?'PLAYER '+d.player.name+' DEFEATED':null,deadC?'CPU '+d.cpu.name+' DEFEATED':null].filter(Boolean).join(' ／ ');const token=duelToken24;setTimeout(()=>{if(token!==duelToken24||d.ended||d.phase!=='switch')return;const sides=advanceMatch27(d);const message=sides.map(side=>{const x=side==='player'?d.playerTeam[d.pIndex]:d.cpuTeam[d.cIndex];return(side==='player'?'PLAYER':'CPU')+' '+x.position+' '+x.card.name+' 登場！';}).join(' ／ ');d.logs.push('<b>'+message+'</b> 勝者は残りHPで続投。');renderDuel24();$('#duelMessage24').textContent=message;$('#duelFormula24').innerHTML='勝ち残ったカードのHPと鼓舞の使用状態は、そのまま引き継ぎます。';$('#duelSkill24').innerHTML='';entrance261(sides);for(const side of sides){const el=$('#'+side+'Fighter24');el.classList.add('team-enter27');setTimeout(()=>el.classList.remove('team-enter27'),750);}},matchMedia('(prefers-reduced-motion: reduce)').matches?200:1150);}else{d.round++;d.clashTurn++;}
 renderDuel24();for(const side of ['player','cpu']){const el=$('#'+side+'Fighter24');el.classList.remove('impact24');void el.offsetWidth;el.classList.add('impact24');}
 $('#duelFormula24').innerHTML=`<b>与えたダメージ ${r.toCPU}</b><br>能力${r.player.stat} ＋ 出目${da} ＋ レア${r.player.rare} ＋ 作戦${r.player.stance}${r.player.skillAttack?` ＋ 特技${r.player.skillAttack}`:''}${r.player.pressure?` ＋ 激戦${r.player.pressure}`:''} − 相手の守り${r.cpu.defense}${r.cpu.skillDefense?` − 特技${r.cpu.skillDefense}`:''}<br><small>受けたダメージ ${r.toPlayer} ／ 同時に攻撃</small>`;
 $('#duelSkill24').innerHTML=[r.player.active?`あなた：${d.player.skill}！`:null,r.cpu.active?`CPU：${d.cpu.skill}！`:null].filter(Boolean).join('<br>');
};
